<div class="card shadow-sm mb-3"><div class="card-body"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="unit-rate-status-filter">Revision Status</label><select class="form-select" id="unit-rate-status-filter" data-master-filter data-table-target="unit-rate-table" data-column="8"><option value="">All statuses</option><option>DRAFT</option><option>APPROVED</option></select></div><div class="col-md-4"><label class="form-label" for="unit-rate-validation-filter">Rate Completeness</label><select class="form-select" id="unit-rate-validation-filter" data-master-filter data-table-target="unit-rate-table" data-column="9"><option value="">All</option><option>Complete</option><option>Missing Rates</option><option>Unrated Equipment</option></select></div></div></div></div>
